CREATE TABLE IF NOT EXISTS "model_forward_rules" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "model_name" TEXT NOT NULL, "enabled" BOOLEAN DEFAULT true, "route_id" INTEGER, "notes" TEXT, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'));
CREATE TABLE IF NOT EXISTS "model_forward_targets" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "rule_id" INTEGER NOT NULL, "site_id" INTEGER NOT NULL, "account_id" INTEGER NOT NULL, "token_id" INTEGER, "upstream_model" TEXT NOT NULL, "channel_id" INTEGER, "weight" INTEGER DEFAULT 10, "enabled" BOOLEAN DEFAULT true, "sort_order" INTEGER DEFAULT 0, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("account_id") REFERENCES "accounts"("id") ON DELETE CASCADE, FOREIGN KEY ("rule_id") REFERENCES "model_forward_rules"("id") ON DELETE CASCADE, FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE, FOREIGN KEY ("token_id") REFERENCES "account_tokens"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "model_forward_rules_model_name_unique" ON "model_forward_rules" ("model_name");
CREATE UNIQUE INDEX "model_forward_targets_rule_account_model_unique" ON "model_forward_targets" ("rule_id", "account_id", "upstream_model");
CREATE INDEX "model_forward_rules_enabled_idx" ON "model_forward_rules" ("enabled");
CREATE INDEX "model_forward_rules_route_id_idx" ON "model_forward_rules" ("route_id");
CREATE INDEX "model_forward_targets_account_id_idx" ON "model_forward_targets" ("account_id");
CREATE INDEX "model_forward_targets_channel_id_idx" ON "model_forward_targets" ("channel_id");
CREATE INDEX "model_forward_targets_rule_sort_idx" ON "model_forward_targets" ("rule_id", "sort_order");
CREATE INDEX "model_forward_targets_site_id_idx" ON "model_forward_targets" ("site_id");
